    var cs={name:"Morwen",cls:"Sorcerer",level:3,hp:20,maxHp:20,stats:{},abilities:[],spells:[],inventory:[],conditions:[],relationships:[]};
    worldState.npcs.push({name:"Morwen",partyMember:true,isPC:true,status:"ally",charSheet:cs});
