  section("STT name correction (v1.330)");
  function __sttRoster(){return [{word:"Frizwick"},{word:"Morwen"},{word:"Zethran"},{word:"Ammut"},{word:"Daeris"},{word:"Hemlock"},{word:"Sandpoint"},{word:"Sandru"},{word:"Aldus"},{word:"Quink"}];}
