  t("RAG location scoring resolves e.l: a scene stamped under the merged name still scores for the canonical location",function(){
    makeGeoWorld();
    delete worldState.ragMemory;/* RAG standard-on */
    applyMuts("[MERGE:location|Sandpoint|Sandpoint, Varisia]");
    worldState.world.location="Sandpoint";worldState.world.sublocation=null;
    worldState.turn=1560;
    var i;worldState.transcript=[];
    for(i=0;i<40;i++)worldState.transcript.push({r:(i%2?"gm":"player"),x:"filler turn "+i,t:i,e:(i%2?{n:[],l:"Thistletop",q:[]}:undefined)});
    worldState.transcript[21]={r:"gm",x:"The harbor chain rattles as the gate opens.",t:21,e:{n:[],l:"Sandpoint, Varisia",q:[]}};
    sessionLog=[];
    ragRetrieve("I look around the harbor");
    var cands=ragRetrieve._cands||[],hit=false;
    for(i=0;i<cands.length;i++){if(cands[i].t===21)hit=true;}
    return hit?true:"the merged-name e.l stamp scored zero — historical scenes go invisible after a merge (the A0 arm-2 property lost)";
  });
  t("locReparent: parent set through resolution, world→sub transition is parent-based, blueprint export skips it, pre-image archived",function(){
    makeGeoWorld();
    memory.map.nodes["Sandpoint Glassworks"]={firstVisit:136,visits:1,description:"Furnace heat.",parent:null,npcs:[],items:[],size:null,travelMins:null,lastVisit:1529};
    var R={muts:[],turn:worldState.turn};
    locReparent("Sandpoint Glassworks","Sandpoint, Varisia",R);/* target named by an alias-to-be */
    applyMuts("[MERGE:location|Sandpoint|Sandpoint, Varisia]");
    var n=memory.map.nodes["Sandpoint Glassworks"];
    if(!n)return "reparented node vanished";
    if(locResolve(n.parent)!=="Sandpoint")return "parent does not resolve to the canonical: "+n.parent;
    if(!locIsSub("Sandpoint Glassworks"))return "world-ness must derive from parent, not key shape";
    worldState.world.location="Sandpoint";worldState.world.sublocation=null;
    var g=buildGeoBlock();
    if(g.indexOf("Sandpoint Glassworks")<0)return "reparented child missing from the sub listing";
    var bp=buildBlueprintFromGame();
    var names=bp.locations.map(function(l){return l.name;});
    if(names.indexOf("Sandpoint Glassworks")>=0)return "blueprint export still treats the reparented child as a world location";
    var im=memory.archive.identityMerges,found=false,i;
    for(i=0;i<(im||[]).length;i++){if(im[i].op==="reparent"&&im[i].key==="Sandpoint Glassworks")found=true;}
    return found?true:"reparent pre-image not archived";
  });
  t("locSplit: successors minted with kind/endpoints, facts and children allocated, fused key tombstones to the primary, edges re-pointed per allocation",function(){
    makeGeoWorld();
    memory.map.nodes["Varisia - North Road"]={firstVisit:766,visits:8,description:"A rutted trade road.",parent:null,npcs:[],items:[],size:null,travelMins:null,
      stateNotes:[{n:"washed-out bridge near the fork",t:800},{n:"giant tracks in the mud",t:1300}]};
    memory.map.nodes["Varisia - North Road|Crossroads Camp"]={firstVisit:900,visits:1,description:null,parent:"Varisia - North Road",npcs:[],items:[],size:null,travelMins:null};
    memory.map.edges.push({from:"Sandpoint",to:"Varisia - North Road",turn:766});
    memory.map.edges.push({from:"Varisia - North Road",to:"Jorgenfist",turn:1340});
    memory.map.nodes["Jorgenfist"]={firstVisit:1340,visits:0,description:null,parent:null,npcs:[],items:[],size:null,travelMins:null};
    memory.npcs["Bethana"].lastSeenAt="Varisia - North Road";
    var R={muts:[],turn:worldState.turn};
    locSplit("Varisia - North Road",{
      primary:"North Road (Magnimar–Sandpoint)",
      successors:[
        {key:"North Road (Magnimar–Sandpoint)",kind:"route",endpoints:["Magnimar","Sandpoint"],take:{stateNotes:[0],children:["Varisia - North Road|Crossroads Camp"],edges:["Sandpoint"]}},
        {key:"North Road (Magnimar–Jorgenfist)",kind:"route",endpoints:["Magnimar","Jorgenfist"],take:{stateNotes:[1],children:[],edges:["Jorgenfist"]}}
      ]},R);
    var p=memory.map.nodes["North Road (Magnimar–Sandpoint)"],s=memory.map.nodes["North Road (Magnimar–Jorgenfist)"];
    if(!p||!s)return "successor nodes not minted";
    if(memory.map.nodes["Varisia - North Road"])return "fused node survived the split";
    if(p.kind!=="route"||!p.endpoints||p.endpoints.join(",")!=="Magnimar,Sandpoint")return "kind/endpoints not written";
    if(p.visits!==8)return "primary did not inherit the numeric record";
    if(p.stateNotes.length!==1||p.stateNotes[0].n.indexOf("washed-out")<0)return "primary allocation wrong";
    if(s.stateNotes.length!==1||s.stateNotes[0].n.indexOf("giant tracks")<0)return "secondary allocation wrong";
    if(locResolve("Varisia - North Road")!=="North Road (Magnimar–Sandpoint)")return "fused key does not tombstone to the primary";
    var ch=memory.map.nodes["Varisia - North Road|Crossroads Camp"];
    if(!ch||locResolve(ch.parent)!=="North Road (Magnimar–Sandpoint)")return "child not re-parented to its successor";
    var toP=0,toS=0,i;
    for(i=0;i<memory.map.edges.length;i++){var e2=memory.map.edges[i];
      if(e2.from==="North Road (Magnimar–Sandpoint)"||e2.to==="North Road (Magnimar–Sandpoint)")toP++;
      if(e2.from==="North Road (Magnimar–Jorgenfist)"||e2.to==="North Road (Magnimar–Jorgenfist)")toS++;
      if(e2.from==="Varisia - North Road"||e2.to==="Varisia - North Road")return "an edge still names the fused key";}
    if(!(toP>=1&&toS>=1))return "edges not re-pointed per allocation ("+toP+"/"+toS+")";
    if(locResolve(memory.npcs["Bethana"].lastSeenAt)!=="North Road (Magnimar–Sandpoint)")return "historical lastSeenAt does not resolve to the primary";
    var im=memory.archive.identityMerges,found=false;
    for(i=0;i<(im||[]).length;i++){if(im[i].op==="split"&&im[i].key==="Varisia - North Road")found=true;}
    return found?true:"split pre-image not archived";
  });
  t("repair census (dev core): finds shadow pairs, byte-identical-description pairs, and same-parent leaf variants — and classifies NOTHING",function(){
    if(typeof locRepairCensus!=="function")return "locRepairCensus missing (dev/loc-repair-core.js not engine-visible)";
    makeGeoWorld();
    memory.map.nodes["Sandpoint - Rusty Dragon"]={firstVisit:80,visits:1,description:null,parent:null,npcs:[],items:[],size:null,travelMins:null};
    memory.map.nodes["Sandpoint|Sandpoint - Rusty Dragon"]={firstVisit:81,visits:14,description:null,parent:"Sandpoint",npcs:[],items:[],size:null,travelMins:null};
    memory.map.nodes["Sandpoint, Varisia"].description="A town on the cliffs.";/* byte-identical desc pair */
    var groups=locRepairCensus();
    var kinds={},i;for(i=0;i<groups.length;i++){kinds[groups[i].evidence]=1;if(groups[i].classification!=="undecided")return "the census auto-classified a group — adjudication is human (Sol §1)";}
    if(!kinds["shadow"])return "shadow pair (world X vs Parent|X) not found";
    if(!kinds["identical-description"])return "byte-identical description pair not found";
    if(!kinds["leaf-variant"])return "same-parent leaf containment pair (Rusty Dragon vs Sandpoint - Rusty Dragon) not found";
    return true;
  });
  // ═══ #157: item-bible-driven inventory organization (Sol's spec, DOC/Research/DOC_inventory_reorganization.html) ═══
  // View-only grouping: one registry, one pure view model, Unclassified as a SAFETY state (never
  // silently Mundane, never dropped), no fuzzy matching — aliases are exact-after-normalization
  // and collision-refused. The stored inventory array is never reordered or rewritten.
  section("inventory organization (#157): registry, grouping, aliases, safety states");
  function makeInvWorld(){
    makeIdWorld();
    worldState.itemBible={};/* overlay-staged entries keep these tests independent of static-bible content */
    return worldState;
  }
  t("INVENTORY_CATEGORY_REGISTRY: the seven ids in fixed priority order, position IS the priority",function(){
    if(typeof INVENTORY_CATEGORY_REGISTRY==="undefined")return "registry missing";
    var ids=INVENTORY_CATEGORY_REGISTRY.map(function(c){return c.id;}).join(",");
    if(ids!=="weapon,armor,quest,consumable,tool,treasure,mundane")return "order wrong: "+ids;
    var i;for(i=0;i<INVENTORY_CATEGORY_REGISTRY.length;i++){if(!INVENTORY_CATEGORY_REGISTRY[i].label)return "missing label at "+i;if(INVENTORY_CATEGORY_REGISTRY[i].rank!==undefined)return "no separate numeric ranks — array position is the priority (Sol §3.1)";}
    return true;
  });
  t("groupInventory precedence: weapon+quest files under Weapons, consumable+quest under Quest; the full-seven entry under Weapons",function(){
    makeInvWorld();
    worldState.itemBible["witchlight blade"]={category:"weapon",inventoryCategories:["weapon","quest"],aliases:[],effect:"Glows near lies.",uses:"at-will",value:"N/A"};
    worldState.itemBible["amber vial"]={category:"consumable",inventoryCategories:["quest","consumable"],aliases:[],effect:"N/A",uses:"single use",value:"N/A"};
    worldState.itemBible["everything token"]={category:"mundane",inventoryCategories:["weapon","armor","quest","consumable","tool","treasure","mundane"],aliases:[],effect:"N/A",uses:"N/A",value:"N/A"};
    var g=groupInventory(["Witchlight blade","Amber vial","Everything token"]);
    function sec(id){var i;for(i=0;i<g.length;i++){if(g[i].id===id)return g[i];}return null;}
    if(!sec("weapon")||sec("weapon").rows.length!==2)return "Weapons should hold the blade AND the all-seven token: "+JSON.stringify(g.map(function(x){return x.id+":"+x.rows.length;}));
    if(!sec("quest")||sec("quest").rows[0].raw!=="Amber vial")return "consumable+quest must file under Quest (registry order), got: "+JSON.stringify(sec("quest"));
    return sec("consumable")===null?true:"the vial must not ALSO appear under Consumables (exactly once)";
  });
  t("legacy scalar-only entries group by their category; invalid metadata and unknown items land in Unclassified (never Mundane, never dropped)",function(){
    makeInvWorld();
    worldState.itemBible["lockpicks"]={category:"tool",effect:"N/A",uses:"reusable",value:"25 gp"};/* legacy shape — no array */
    worldState.itemBible["cursed orb"]={category:"weapon",inventoryCategories:[],aliases:[],effect:"N/A",uses:"N/A",value:"N/A"};/* invalid: empty array */
    worldState.itemBible["odd idol"]={category:"treasure",inventoryCategories:["treasure","haunted"],aliases:[],effect:"N/A",uses:"N/A",value:"N/A"};/* invalid: unknown id */
    var g=groupInventory(["Lockpicks","Cursed orb","Odd idol","Total mystery item"]);
    function sec(id){var i;for(i=0;i<g.length;i++){if(g[i].id===id)return g[i];}return null;}
    if(!sec("tool")||sec("tool").rows[0].key!=="lockpicks")return "legacy scalar entry did not derive [category]";
    var u=sec("unclassified");
    if(!u)return "no Unclassified section";
    var names=u.rows.map(function(r){return r.raw;}).join("|");
    if(names.indexOf("Cursed orb")<0)return "empty-array metadata must land in Unclassified, not be repaired silently";
    if(names.indexOf("Odd idol")<0)return "unknown category id must land in Unclassified";
    if(names.indexOf("Total mystery item")<0)return "an unknown item must stay VISIBLE in Unclassified";
    if(sec("mundane"))return "nothing here may default to Mundane — it is a positive classification (Sol §3.4)";
    return g[g.length-1].id==="unclassified"?true:"Unclassified must render last";
  });
  t("exactly-once with source indexes and stable relative order — the grouped view is a permutation carrying original positions",function(){
    makeInvWorld();
    worldState.itemBible["longsword"]={category:"weapon",inventoryCategories:["weapon"],aliases:[],effect:"N/A",uses:"at-will",value:"15 gp"};
    worldState.itemBible["rope"]={category:"tool",inventoryCategories:["tool"],aliases:[],effect:"N/A",uses:"reusable",value:"1 gp"};
    var inv=["Rope x2","Longsword","Mystery A","Rope","Longsword (notched)"];
    var g=groupInventory(inv),flat=[],i,j;
    for(i=0;i<g.length;i++){for(j=0;j<g[i].rows.length;j++)flat.push(g[i].rows[j]);}
    if(flat.length!==inv.length)return "row count changed: "+flat.length+"/"+inv.length;
    for(i=0;i<flat.length;i++){if(inv[flat[i].sourceIndex]!==flat[i].raw)return "sourceIndex broken at '"+flat[i].raw+"'";}
    var weap=null;for(i=0;i<g.length;i++){if(g[i].id==="weapon")weap=g[i];}
    if(!weap||weap.rows.length!==2)return "both longswords must file under Weapons";
    if(!(weap.rows[0].sourceIndex===1&&weap.rows[1].sourceIndex===4))return "relative order inside a section must follow the stored array";
    return true;
  });
  t("aliases resolve canonically through itemLookup — grouping, tooltip, and GM injection all agree (never a UI-only resolver)",function(){
    makeInvWorld();
    worldState.itemBible["corked vial"]={category:"consumable",inventoryCategories:["consumable"],aliases:["small corked vial, violet residue"],effect:"One measured dose of numbweed tincture.",uses:"single use",value:"12 gp"};
    var e=itemLookup("Small corked vial, violet residue x2");
    if(!e||e.effect.indexOf("numbweed")<0)return "alias did not resolve through itemLookup";
    var g=groupInventory(["Small corked vial, violet residue x2"]);
    if(g[0].id!=="consumable")return "alias-resolved item did not group by its entry";
    /* tooltip agreement is structural — itemTip (ui-panels.js, outside the engine subset)
       delegates to this same itemLookup; the cross-surface probe that matters is injection: */
    worldState.character.inventory=["Small corked vial, violet residue x2"];
    var blk=buildItemBibleBlock();
    return blk.indexOf("numbweed")>=0?true:"GM item-canon injection did not pick up the alias-resolved item — a UI-only resolver would now disagree with the prompt (Sol §4)";
  });
  t("alias collisions refuse loudly and resolve as Unclassified — never a winner by object order",function(){
    makeInvWorld();
    worldState.itemBible["iron key"]={category:"tool",inventoryCategories:["tool"],aliases:[],effect:"N/A",uses:"reusable",value:"N/A"};
    worldState.itemBible["warden's key"]={category:"quest",inventoryCategories:["quest"],aliases:["iron key"],effect:"N/A",uses:"N/A",value:"N/A"};/* alias shadows a LIVE key */
    worldState.itemBible["red flask"]={category:"consumable",inventoryCategories:["consumable"],aliases:["strange flask"],effect:"N/A",uses:"single use",value:"N/A"};
    worldState.itemBible["blue flask"]={category:"consumable",inventoryCategories:["consumable"],aliases:["strange flask"],effect:"N/A",uses:"single use",value:"N/A"};/* duplicate alias */
    var warned=false,ow=console.warn;console.warn=function(){warned=true;};
    var e1,g;try{e1=itemLookup("Iron key");g=groupInventory(["Strange flask"]);}finally{console.warn=ow;}
    if(!e1||e1.category!=="tool")return "an exact key must always beat an alias claim";
    if(!warned)return "collisions were silent";
    return g[g.length-1].id==="unclassified"&&g[g.length-1].rows[0].raw==="Strange flask"?true:"an ambiguous alias must resolve as Unclassified: "+JSON.stringify(g);
  });
  t("classification-only entries (effect N/A) group correctly and stay OUT of the GM item-canon block",function(){
    makeInvWorld();
    worldState.itemBible["quest letter"]={category:"quest",inventoryCategories:["quest"],aliases:[],effect:"N/A",uses:"N/A",value:"N/A"};
    var g=groupInventory(["Quest letter"]);
    if(g[0].id!=="quest")return "classification-only entry did not group";
    worldState.character.inventory=["Quest letter"];
    var blk=buildItemBibleBlock();
    return blk.indexOf("quest letter")<0?true:"an N/A-effect entry leaked into the injected canon — organization must not force premature mechanics (Sol §3.5)";
  });
  t("itemDefAccept persists a validated inventoryCategories array; legacy acceptance (scalar only) still lands and derives at read",function(){
    makeInvWorld();
    worldState.pendingItemDefs=[{key:"smoke bomb",name:"Smoke Bomb",entry:{category:"consumable",inventoryCategories:["consumable","tool"],effect:"Bursts into thick smoke.",uses:"single use",value:"40 gp"}},
                                {key:"plain marble",name:"Plain Marble",entry:{category:"mundane",effect:"N/A",uses:"N/A",value:"N/A"}}];
    if(!itemDefAccept("smoke bomb"))return "accept failed";
    if(JSON.stringify(worldState.itemBible["smoke bomb"].inventoryCategories)!=='["consumable","tool"]')return "array did not persist on acceptance";
    if(!itemDefAccept("plain marble"))return "legacy-shaped accept failed";
    var g=groupInventory(["Plain Marble","Smoke Bomb"]);
    function sec(id){var i;for(i=0;i<g.length;i++){if(g[i].id===id)return g[i];}return null;}
    if(!sec("mundane"))return "legacy overlay entry did not derive [category] at read";
    return sec("consumable")&&sec("consumable").rows[0].raw==="Smoke Bomb"?true:"multi-category acceptance did not group by precedence";
  });
  t("empty inventory groups to an empty list (renderers keep the single Empty message — no seven-heading scaffold)",function(){
    makeInvWorld();
    var g=groupInventory([]);
    return g.length===0?true:"expected zero sections for an empty inventory, got "+g.length;
  });

  // ═══ #158: the clock phase-mismatch detector (Sol-amended spec, adjudicated 2026-08-09) ═══
  // Prose narrated a phase the clock never reached and nothing could notice. The detector
  // recognizes a HIGH-CONFIDENCE current-phase assertion in committed narration (one vocabulary:
  // \b-anchored prose forms DERIVED from TIME_PHASES), compares against the post-applyMuts clock
  // by BAND distance, and arms the one-shot GM-decides nudge. Never auto-advances.
  section("#217 schedule near-duplicate dedupe — the triple-booked bracelet deadline");
  // Field origin (the live t2097 save, 2026-08-22): the clock carried THREE deadlines for one
  // errand — "Return to Wyla Ashvane's shop to collect the four cold-warded bracelets" (7.4d),
  // "Collect the completed ember-rune warding bracelets" (6.8d), "...finish tempering ... in
  // three days" (2.9d) — all three injected into UPCOMING every turn, and the contradiction
  // reached the fiction (Wyla arguing six days at t2087 while an entry said three).
  // fileFutureEvent got this exact tooth as #29①; scheduleAdd never did. Same fingerprint
  // (feNearDup — #150 extracted it precisely so schedule code could share thresholds).
  var __WYLA=[
    "Return to Wyla Ashvane's shop to collect the four cold-warded bracelets",
    "Collect the completed ember-rune warding bracelets from Wyla Ashvane",
    "Wyla Ashvane will finish tempering and quenching the four mountain warding bracelets in three days, assisted by Daeris's forge-warding and the party's labor."
  ];
  t("#217 a re-phrased deadline REFRESHES the existing entry instead of filing a twin (last-write-wins, the exact-match semantics)",function(){
    makeWorld();worldState.clock={min:24750,schedule:[]};
    scheduleAdd(__WYLA[0],"10d");
    var _i=console.info;console.info=function(){};
    try{scheduleAdd(__WYLA[1],"6d");}finally{console.info=_i;}
    var sch=worldState.clock.schedule;
    if(sch.length!==1)return "a re-phrased deadline filed a twin: "+sch.length+" entries";
    if(sch[0].label!==__WYLA[0])return "the fold rewrote the original label: "+sch[0].label;
    return sch[0].dueMin===24750+6*1440?true:"the fold did not adopt the newest deadline: "+sch[0].dueMin;
  });
  t("#217 genuinely different business still files separately (the Hemlock threshold)",function(){
    makeWorld();worldState.clock={min:0,schedule:[]};
    scheduleAdd("Meet Wyla at the shop","2d");
    scheduleAdd("Ambush the caravan on the north road","3d");
    return worldState.clock.schedule.length===2?true:"different business was folded: "+JSON.stringify(worldState.clock.schedule.map(function(e){return e.label;}));
  });
  t("#217 the load sweep collapses the live triple to the freshest-born entry, archives the removed pair, and is idempotent",function(){
    makeWorld();
    worldState.clock={min:28511,schedule:[
      {id:"sch1_39150",label:__WYLA[0],dueMin:39150,born:24750},
      {id:"sch2_38325",label:__WYLA[1],dueMin:38325,born:25365},
      {id:"sch3_32666",label:__WYLA[2],dueMin:32666,born:28346}
    ]};
    var _w=console.warn,_i=console.info;console.warn=function(){};console.info=function(){};
    try{scheduleDedupSweep();}finally{console.warn=_w;console.info=_i;}
    var sch=worldState.clock.schedule;
    if(sch.length!==1)return "sweep left "+sch.length+" entries";
    if(sch[0].id!=="sch3_32666")return "sweep kept the wrong entry (want freshest-born): "+sch[0].id;
    var reps=(worldState.clock.repairs||[]).filter(function(r){return r.id==="217-schedule-dedupe";});
    if(!reps.length)return "removed entries were not archived to clock.repairs";
    if(!reps[0].removed||reps[0].removed.length!==2)return "the archive does not carry both removed entries: "+JSON.stringify(reps[0]);
    console.warn=function(){};console.info=function(){};
    try{scheduleDedupSweep();}finally{console.warn=_w;console.info=_i;}
    if(worldState.clock.schedule.length!==1)return "re-run mutated a clean schedule";
    return (worldState.clock.repairs||[]).filter(function(r){return r.id==="217-schedule-dedupe";}).length===1?true:"re-run minted a second repair record";
  });
  t("#217 the sweep never touches distinct deadlines and never moves the clock scalar",function(){
    makeWorld();
    worldState.clock={min:5000,schedule:[
      {id:"a",label:"Meet Wyla at the shop",dueMin:6000,born:4000},
      {id:"b",label:"Ambush the caravan on the north road",dueMin:7000,born:4500}
    ]};
    scheduleDedupSweep();
    if(worldState.clock.schedule.length!==2)return "distinct deadlines were folded";
    return worldState.clock.min===5000?true:"the sweep moved the clock scalar";
  });

  // ── #235 (JP0-10, joint review 2026-08-27): the schedule store's fold was too loose for its
  // authority level — feNearDup's floor (2 shared stemmed tokens covering half the smaller
  // fingerprint) silently merged DISTINCT deadlines sharing two ordinary words ("meet the
  // innkeeper at dawn" / "meet the ferryman at dawn"): one countdown corrupted and served as
  // canon every turn, the other errand untrackable while the kept entry lived. The schedule
  // comparator now demands shared>=3 OR a strict token subset; the Wyla bracelet rephrasings
  // (#217's field fixtures, 4-5 shared tokens) still fold. The fold is also HONEST at the muts
  // line now — it names both labels instead of pairing the kept label with the new countdown.
  section("#235 — schedule fold precision (the innkeeper/ferryman class)");
  t("#235: distinct deadlines sharing two ordinary tokens file SEPARATELY",function(){
    makeWorld();worldState.clock={min:0,schedule:[]};
    scheduleAdd("Meet the innkeeper at dawn","1d");
    var _i=console.info;console.info=function(){};
    try{scheduleAdd("Meet the ferryman at dawn","2d");}finally{console.info=_i;}
    var sch=worldState.clock.schedule;
    if(sch.length!==2)return "two different errands were folded into one deadline: "+JSON.stringify(sch.map(function(e){return e.label;}));
    return sch[0].dueMin===1440&&sch[1].dueMin===2880?true:"countdowns crossed: "+JSON.stringify(sch.map(function(e){return e.dueMin;}));
  });
  t("#235: the load sweep also refuses the two-token false fold",function(){
    makeWorld();
    worldState.clock={min:100,schedule:[
      {id:"a",label:"Meet the innkeeper at dawn",dueMin:1540,born:50},
      {id:"b",label:"Meet the ferryman at dawn",dueMin:2980,born:60}
    ]};
    var _w=console.warn,_i=console.info;console.warn=function(){};console.info=function(){};
    try{scheduleDedupSweep();}finally{console.warn=_w;console.info=_i;}
    return worldState.clock.schedule.length===2?true:"the sweep folded distinct deadlines";
  });
  t("#235: a strict-subset restatement still folds at two shared tokens",function(){
    makeWorld();worldState.clock={min:0,schedule:[]};
    scheduleAdd("Meet the innkeeper at dawn","1d");
    var _i=console.info;console.info=function(){};
    try{scheduleAdd("Meet the innkeeper","2d");}finally{console.info=_i;}
    var sch=worldState.clock.schedule;
    return sch.length===1&&sch[0].dueMin===2880?true:"a subset restatement stopped folding: "+JSON.stringify(sch.map(function(e){return e.label;}));
  });
  t("#235: the SCHEDULE muts line is honest about a fold — it names BOTH labels",function(){
    makeWorld();worldState.clock={min:0,schedule:[]};
    scheduleAdd("Return to Wyla Ashvane's shop to collect the four cold-warded bracelets","10d");
    var _i=console.info;console.info=function(){};var r;
    try{r=applyMuts("[SCHEDULE:Collect the completed ember-rune warding bracelets from Wyla Ashvane|6d]");}finally{console.info=_i;}
    if(worldState.clock.schedule.length!==1)return "the Wyla rephrasing stopped folding: "+worldState.clock.schedule.length;
    var line=(r&&r.muts?r.muts:[]).filter(function(m){return m.indexOf("Schedule")>=0||m.indexOf("Scheduled")>=0;})[0];
    if(!line)return "no schedule muts line: "+JSON.stringify(r&&r.muts);
    if(line.indexOf("ember-rune")<0)return "the fold hides the incoming label: "+line;
    return line.indexOf("cold-warded")>=0?true:"the fold does not name the kept deadline: "+line;
  });

  section("#223 the undefined-item nudge — nothing ever asked what Giant's Bane does");
  // Root cause of the field incident: a mechanics-bearing item entered the pack and NOTHING
  // asked for its canon. There are nudges for duplicate items, misattributed items and ghost
  // consumables — none for "you are carrying something with mechanics and no definition". So
  // the GM adlibbed, because the engine never established the fact for it to read. The nudge
  // asks for one [ITEM_DEF:] proposal, which the PLAYER then confirms (#81) — the engine never
  // mints item canon on its own.
  function __undefWorld(){
    makeWorld();
    worldState.combat=null;delete worldState.itemDefCandidate;
    worldState.character.inventory=[];
    return worldState;
  }
  t("#223 ACQUIRING a mechanics-bearing item with no canon arms the nudge, naming it and the [ITEM_DEF:] shape",function(){
    __undefWorld();
    applyMuts("[ITEM_GAINED:Vial of giant's bane]");
    var n=buildUndefinedItemNudge();
    if(!n)return "nothing fired for a carried item the bible gives no effect for";
    if(n.indexOf("giant's bane")<0)return "the note does not name the item: "+n;
    if(n.indexOf("[ITEM_DEF:")<0)return "the note does not teach the tag that actually creates canon: "+n;
    if(!/confirm/i.test(n))return "the note omits that the player confirms — it would promise canon the GM cannot write alone";
    return true;
  });
  t("#223 an item the bible fully defines never triggers it",function(){
    __undefWorld();
    var k=null,kk;
    for(kk in ITEM_BIBLE){var e=ITEM_BIBLE[kk];if(e.effect&&e.effect!=="N/A"&&e.category!=="mundane"&&e.category!=="treasure"){k=kk;break;}}
    if(!k)return "fixture broke: no fully-defined item in the bible";
    applyMuts("[ITEM_GAINED:"+k+"]");
    return buildUndefinedItemNudge()===""?true:"a defined item still asked for a definition";
  });
  t("#294B ① (owner: ALL items need a description): plain gear asks too — the old mundane skip-list is gone; an inline \"—\" description exempts itself",function(){
    __undefWorld();
    applyMuts("[ITEM_GAINED:Bedroll]");
    var n=buildUndefinedItemNudge();
    if(!n||n.indexOf("bedroll")<0)return "a bedroll no longer asks — the mundane skip-list is back: "+JSON.stringify(n);
    __undefWorld();
    applyMuts("[ITEM_GAINED:Runed knucklebone — hums faintly near ley lines]");
    if(buildUndefinedItemNudge()!=="")return "an item carrying its own inline description was asked about anyway";
    __undefWorld();
    applyMuts("[ITEM_GAINED:Runed knucklebone]");
    return buildUndefinedItemNudge()!==""?true:"fixture: the same item WITHOUT a description must ask (otherwise the exemption assertion proves nothing)";
  });
  t("#294B ①: asked ONCE per item per campaign — a re-gained key never re-arms; the latch is stamped at delivery, restored with the candidate on a dead turn, and bounded",function(){
    __undefWorld();delete worldState.itemDefAsked;
    applyMuts("[ITEM_GAINED:Vial of giant's bane]");
    if(!buildUndefinedItemNudge())return "fixture: first ask did not fire";
    if(!worldState.itemDefAsked||worldState.itemDefAsked["vial of giant's bane"]==null)return "delivery did not stamp the asked latch";
    applyMuts("[ITEM_LOST:Vial of giant's bane][ITEM_GAINED:Vial of giant's bane]");
    if(worldState.itemDefCandidate)return "a re-gained key re-armed the candidate — the GM would be nagged every time it changes hands";
    if(buildUndefinedItemNudge()!=="")return "the second ask fired";
    /* dead-turn restore: the latch rides NOTE_LATCH_FIELDS beside the candidate */
    if(NOTE_LATCH_FIELDS.indexOf("itemDefAsked")<0)return "itemDefAsked is not in NOTE_LATCH_FIELDS — a dead turn would leave the item asked-but-never-delivered";
    delete worldState.itemDefAsked;applyMuts("[ITEM_GAINED:Runed knucklebone]");
    var snap=snapshotNoteLatches();buildUndefinedItemNudge();restoreNoteLatches(snap);
    if(worldState.itemDefAsked&&worldState.itemDefAsked["runed knucklebone"]!=null)return "a dead provider turn kept the asked stamp (#151) — the note is lost forever";
    if(!buildUndefinedItemNudge())return "the restored candidate did not re-deliver";
    /* bound */
    var i;worldState.itemDefAsked={};for(i=0;i<ITEM_DEF_ASKED_CAP+5;i++)_itemDefMarkAsked("k"+i,i);
    var ks=Object.keys(worldState.itemDefAsked);
    if(ks.length!==ITEM_DEF_ASKED_CAP)return "asked map unbounded: "+ks.length;
    return worldState.itemDefAsked["k0"]==null&&worldState.itemDefAsked["k"+(ITEM_DEF_ASKED_CAP+4)]!=null?true:"eviction did not drop the oldest";
  });
  t("#223 combat-silent, one-shot, and restored when a provider turn dies (#151)",function(){
    __undefWorld();
    worldState.combat={round:1,foes:[]};
    applyMuts("[ITEM_GAINED:Vial of giant's bane]");
    if(buildUndefinedItemNudge()!=="")return "it fired mid-combat";
    if(!worldState.itemDefCandidate)return "combat consumed the candidate";
    worldState.combat=null;
    var snap=snapshotNoteLatches();
    if(!buildUndefinedItemNudge())return "fixture broke: it did not fire out of combat";
    if(buildUndefinedItemNudge()!=="")return "it re-fired immediately — no one-shot latch";
    restoreNoteLatches(snap);
    return buildUndefinedItemNudge()!==""?true:"a dead provider turn ate the note (#151)";
  });
  t("#223 the latch key is declared in NOTE_LATCH_FIELDS, so the census cannot rot",function(){
    return NOTE_LATCH_FIELDS.indexOf("itemDefCandidate")>=0?true:"itemDefCandidate is not in NOTE_LATCH_FIELDS — a failed turn would burn the ask silently";
  });

  section("#222 Table Talk knows items (the Giant's Bane incident, field 2026-08-23)");
  // The owner asked Table Talk to treat "giant's bane is a paralytic" as canon. TT refused
  // correctly (it cannot write state) but then MISDIRECTED: "use Sync state if the sheet needs
  // updating" — Sync edits hp/gold/xp/inventory STRINGS and cannot attach a property to an item.
  // The real path is [ITEM_DEF:] on a story turn → the player-confirm modal → worldState.itemBible.
  // Measured on the live t2097 save: the item bible block was absent from the TT prompt entirely,
  // while the capability bible got a full name index + per-question canon. Same data class,
  // opposite treatment. TT's own prime directive calls a confident wrong answer the worst
  // possible outcome here, and this was one.
  function __ttWorld(){
    makeWorld();
    worldState.campName="Probe";worldState.turn=2097;
    worldState.character.inventory=["Vial of giant's bane x3","Rope (50 ft)"];
    return worldState;
  }
  t("#222① the TT prompt carries an ITEM index, the way it already carries the capability index",function(){
    __ttWorld();
    var p=buildTableTalkPrompt("what do I have in my pack?");
    if(p.indexOf("RULES — CAPABILITY BIBLE")<0)return "fixture broke: the capability index is missing too";
    if(p.indexOf("ITEM BIBLE")<0)return "TT still has no item-canon block — it can quote a spell's numbers and nothing about carried gear";
    return true;
  });
  t("#222① a carried item the bible DEFINES comes back with its canon, quotable exactly",function(){
    __ttWorld();
    var k=null,kk;
    for(kk in ITEM_BIBLE){k=kk;break;}
    if(!k)return "fixture broke: ITEM_BIBLE is empty";
    worldState.character.inventory=[k];
    var p=buildTableTalkPrompt("tell me about my "+k);
    if(p.indexOf(itemBibleLine(k,itemLookup(k)))<0)return "the defined item's full canon line is not in the prompt for a question naming it";
    return true;
  });
  t("#222① a CLASSIFICATION-ONLY entry is reported as having no mechanics, never quoted as canon (the actual Giant's Bane shape)",function(){
    __ttWorld();
    // The field case: "vial of giant's bane" HAS a bible entry, but effect "N/A" — it sorts the
    // item into the right inventory section and injects nothing, so buildItemBibleBlock skips it
    // and the GM has no canon either. TT must report that, not print "effect: N/A" as a fact.
    var e=itemLookup("Vial of giant's bane x3");
    if(!e)return "fixture broke: the bible entry this test is about is gone";
    if(e.effect!=="N/A")return "fixture broke: the entry now HAS an effect — repoint this test at another classification-only item";
    var p=buildTableTalkPrompt("what is giant's bane?");
    var i=p.indexOf("ITEM BIBLE"),seg=i<0?"":p.slice(i,i+1600);
    if(!/giant's bane/i.test(seg))return "the carried item is invisible in the item block entirely";
    if(/giant's bane[^\n]*effect: N\/A/i.test(seg))return "TT quotes 'effect: N/A' as if it were canon — the useless-but-authoritative-sounding answer";
    if(!/NO MECHANICS ON RECORD[\s\S]*giant's bane/i.test(seg))return "the classification-only item is not listed under the no-mechanics heading: "+seg.slice(0,260);
    return true;
  });
  t("#222② TT teaches the [ITEM_DEF:] route and never points at Sync for an item PROPERTY",function(){
    __ttWorld();
    var p=buildTableTalkPrompt("giant's bane is a paralytic, add that to canon");
    if(p.indexOf("[ITEM_DEF:")<0)return "TT is not taught the one path that actually makes item canon (#81)";
    if(!/confirm/i.test(p.slice(p.indexOf("[ITEM_DEF:")-400,p.indexOf("[ITEM_DEF:")+400)))return "the [ITEM_DEF:] guidance omits that the PLAYER confirms it — TT would promise canon the GM cannot write alone";
    return true;
  });

  section("#225 orphan combat tags — the four-turn ghost fight (field t2228-2231, 2026-08-23)");
  // The Bronze Bell Warden: [COMBAT_END:fled] closed the fight at t2227, the story re-engaged
  // the warden at t2228, and for FOUR turns every combat tag (ENEMY_HP, COMBAT_ROUND,
  // ENEMY_SLAIN, a second COMBAT_END) hit the null tracker and no-opped with only a console
  // warn — invisible in play, the #16 mobile class. The GM narrated an HP bar that existed
  // nowhere, the player asked Table Talk "how is it not dead at 0 hp", and TT answered
  // CORRECTLY that no state exists — its honesty exposed the gap. The engine's job: make the
  // orphan loud (toast) and recoverable (a note teaching the [COMBAT_START:] re-open).
  function __orphanWorld(){
    makeWorld();__xpCapOff();/* #302: after makeWorld, which resets the cap */worldState.combat=null;
    delete worldState.orphanCombat;
    return worldState;
  }
  t("#225 orphan combat tags arm the record and toast ONCE, naming the ghost fight",function(){
    __orphanWorld();
    var toasts=[],_t=(typeof showToast==="function")?showToast:null;showToast=function(m){toasts.push(String(m));};
    var _w=console.warn;console.warn=function(){};
    try{
      applyMuts("[COMBAT_ROUND:2][ENEMY_HP:Bronze Bell Warden|-9][DICE:attack|24|success]");
      applyMuts("[COMBAT_ROUND:3][ENEMY_HP:Bronze Bell Warden|-11]");
    }finally{console.warn=_w;if(_t)showToast=_t;else showToast=function(){};}
    var q=worldState.orphanCombat;
    if(!q)return "no orphan record armed — the ghost fight stays console-only";
    if(!q.tags||q.tags.indexOf("ENEMY_HP")<0)return "the record does not carry the orphaned tag names: "+JSON.stringify(q);
    var hits=toasts.filter(function(x){return /tracker|encounter|not.*recorded|closed/i.test(x);});
    if(!hits.length)return "no player-visible toast — the no-op stayed silent in play: "+JSON.stringify(toasts);
    if(hits.length>1)return "the toast repeated per response — one loud notice per gap, not a nag: "+hits.length;
    return true;
  });
  t("#225 the nudge teaches the [COMBAT_START:] re-open, one-shot, #151-restorable, and moot once combat is open again",function(){
    __orphanWorld();
    var _w=console.warn,_t=(typeof showToast==="function")?showToast:null;console.warn=function(){};if(_t)showToast=function(){};
    try{applyMuts("[ENEMY_HP:Bronze Bell Warden|-9]");}finally{console.warn=_w;if(_t)showToast=_t;}
    var n=buildOrphanCombatNudge();
    if(!n)return "nothing delivered for an armed orphan record";
    if(n.indexOf("[COMBAT_START:")<0)return "the note does not teach the re-open: "+n;
    if(n.indexOf("applied NOTHING")<0&&!/no.*(effect|record)/i.test(n))return "the note does not say the tags no-opped: "+n;
    if(buildOrphanCombatNudge()!=="")return "the note re-fired immediately — no one-shot latch";
    __orphanWorld();
    var _w2=console.warn;console.warn=function(){};var _t2=(typeof showToast==="function")?showToast:null;if(_t2)showToast=function(){};
    try{applyMuts("[ENEMY_HP:Bronze Bell Warden|-9]");}finally{console.warn=_w2;if(_t2)showToast=_t2;}
    var snap=snapshotNoteLatches();
    if(!buildOrphanCombatNudge())return "fixture broke: second arm did not deliver";
    restoreNoteLatches(snap);
    if(!buildOrphanCombatNudge())return "a dead provider turn ate the note (#151)";
    __orphanWorld();
    var _w3=console.warn;console.warn=function(){};var _t3=(typeof showToast==="function")?showToast:null;if(_t3)showToast=function(){};
    try{applyMuts("[ENEMY_HP:Bronze Bell Warden|-9]");applyMuts("[COMBAT_START:Bronze Bell Warden|14|15|+4|d10|high]");}finally{console.warn=_w3;if(_t3)showToast=_t3;}
    return buildOrphanCombatNudge()===""?true:"the GM already re-opened the fight and the note still nagged";
  });
  t("#225 COMBAT_END over a null tracker records no false outcome and arms no aftermath",function(){
    __orphanWorld();delete worldState.pendingLocState;
    var _w=console.warn;console.warn=function(){};var _t=(typeof showToast==="function")?showToast:null;if(_t)showToast=function(){};
    var r;try{r=applyMuts("[COMBAT_END:victory][XP:150]");}finally{console.warn=_w;if(_t)showToast=_t;}
    var muts=(r&&r.muts)||[];
    for(var i=0;i<muts.length;i++)if(/^Combat:/.test(muts[i]))return "a victory was recorded over a fight that was never open: "+muts[i];
    if(worldState.pendingLocState)return "the #149 aftermath nudge armed for a combat that never existed";
    return worldState.character.xp>=150?true:"the XP beside the orphan close was lost: "+worldState.character.xp;/* #302: the engine's own milestone rides on top — this asserts the payout LANDED */
  });
  t("#225 orphanCombat is in NOTE_LATCH_FIELDS",function(){
    return NOTE_LATCH_FIELDS.indexOf("orphanCombat")>=0?true:"orphanCombat missing from the latch census — a failed turn would burn the ask";
  });
  t("#216fix TIME_CHECK is NOT combat-scoped — an out-of-combat declaration must not trip the UA27 counter",function(){
    // Shipped bug (v1.700, found during the #225 investigation): TIME_CHECK carried nc:1, so the
    // EVERY-response declaration #216 demands incremented __tagNoCombatWarns and console-warned
    // on every peaceful turn — tripwire pollution that made the UA27 counter meaningless.
    makeWorld();worldState.combat=null;
    var before=__tagNoCombatWarns;
    var _w=console.warn;console.warn=function(){};
    try{applyMuts("[TIME_CHECK:morning]");}finally{console.warn=_w;}
    return __tagNoCombatWarns===before?true:"TIME_CHECK outside combat bumped the UA27 no-combat counter (+"+(__tagNoCombatWarns-before)+")";
  });

  section("#216 [TIME_CHECK:] — the read-before-write clock declaration");
  // Field origin (t2175, 2026-08-22): sonnet-5 narrated sundown and camped the party in full
  // dark while the clock read 11:57 AM — and #158's prose recognizer, precision-tuned, was
  // blind to nightfall rendered as pure imagery ("day bleeding out of the sky"). The fix is
  // the #141 forced-checking-space shape: the GM DECLARES the phase as a structured tag before
  // writing prose, and detection becomes a deterministic band comparison instead of prose
  // recognition. THE TAG IS READ-ONLY BY CONSTRUCTION — it never moves the clock; a GM that
  // believes time has passed charges it with [TIME_ADVANCE:] or declares [TIME:].
  function makeTcWorld(offMin){
    makeWorld();
    worldState.clock={min:offMin,schedule:[]};
    delete worldState.phaseMismatch;
    return worldState;
  }
  t("#216 an in-band declaration is silent: no mismatch armed, clock untouched",function(){
    makeTcWorld(357); // 11:57 AM elapsed-of-day
    applyMuts("[TIME_CHECK:midday]");
    if(worldState.phaseMismatch)return "an accurate declaration armed a mismatch";
    return worldState.clock.min===357?true:"the check moved the clock: "+worldState.clock.min;
  });
  t("#216 the t2175 shape: [TIME_CHECK:sundown] against a midday clock arms the GM-decides mismatch and moves NOTHING",function(){
    makeTcWorld(357);
    applyMuts("[TIME_CHECK:sundown]");
    var q=worldState.phaseMismatch;
    if(!q)return "the sundown-at-midday declaration armed nothing — the exact field failure sails through";
    if(!/dusk|sunset|sundown|twilight/i.test(q.label||""))return "armed label wrong: "+JSON.stringify(q);
    if(worldState.clock.min!==357)return "READ-ONLY VIOLATED — the check advanced the clock to "+worldState.clock.min;
    var n=buildPhaseMismatchNudge();
    return n&&n.indexOf("[TIME:")>=0?true:"the armed mismatch did not produce the reconcile nudge: "+n;
  });
  t("#216 the declaration is judged against the PRE-advance clock — the clock the GM actually read",function(){
    makeTcWorld(357);
    applyMuts("[TIME_CHECK:midday][TIME_ADVANCE:8h]");
    if(worldState.phaseMismatch)return "a truthful opening declaration was judged against the post-advance clock";
    return worldState.clock.min===357+480?true:"TIME_ADVANCE lost beside the check: "+worldState.clock.min;
  });
  t("#216 an adjacent-band declaration under the mismatch threshold stays silent (no noisy detector)",function(){
    makeTcWorld(700); // 5:40 PM elapsed-of-day — dusk band starts at 750, 50m of slop
    applyMuts("[TIME_CHECK:dusk]");
    return worldState.phaseMismatch?"a 50-minute slop armed the 4-hour detector":true;
  });
  t("#216 an unmappable label warns loudly and arms nothing",function(){
    makeTcWorld(357);
    var warned=0,_w=console.warn;console.warn=function(){warned++;};
    try{applyMuts("[TIME_CHECK:the storm-dark hour]");}finally{console.warn=_w;}
    if(worldState.phaseMismatch)return "free text armed a mismatch";
    if(!warned)return "an unmappable declaration was silently dropped";
    return worldState.clock.min===357?true:"clock moved on garbage input";
  });
  t("#216 the doc teaches the tag, every canonical label it lists resolves in TIME_PHASES, and the tag strips clean",function(){
    var d=buildStateTagsDoc();
    var m=d.match(/\[TIME_CHECK:[^\]]*\][^(]*\(labels: ([^)]*)\)/);
    if(!m)return "the [TIME_CHECK:] doc line (with its labels clause) is missing from the GM contract";
    var labels=m[1].split(", "),i,j;
    if(labels.length<8)return "labels clause suspiciously short: "+m[1];
    for(i=0;i<labels.length;i++){
      var hit=false;
      for(j=0;j<TIME_PHASES.length;j++)if(TIME_PHASES[j].re.test(labels[i])){hit=true;break;}
      if(!hit)return "doc lists a label TIME_PHASES cannot resolve: "+labels[i];
    }
    if(d.indexOf("never moves the clock")<0&&d.indexOf("never advances the clock")<0)return "the doc does not pin the read-only contract — the [TIME:] confusion is one edit away";
    var clean=cleanTxt("The morning is cold. [TIME_CHECK:morning] Frost rimes the stones.");
    return clean.indexOf("TIME_CHECK")<0?true:"the tag leaked to the player: "+clean;
  });

  section("clock phase-mismatch detector (#158)");
  function makeClockWorld(offMin){
    makeIdWorld();
    worldState.clock={min:offMin,schedule:[]};
    worldState.combat=null;
    delete worldState.phaseMismatch;
    return worldState;
  }
  t("#195④: a PLACE's standing darkness is not a time assertion (the Underbridge class)",function(){
    makeClockWorld(800);
    if(clockPhaseAssertion("The permanent twilight of the Underbridge pressed close around them."))return "'permanent twilight of the Underbridge' read as scene time — the 1:17pm false alarm";
    if(clockPhaseAssertion("Eternal night reigned in the sealed vault."))return "'eternal night' (standing condition) read as scene time";
    if(clockPhaseAssertion("The twilight of the Underbridge swallowed the stair."))return "'twilight of the <Place>' (attribute-of-place) read as scene time";
    var p=clockPhaseAssertion("Twilight settled over the market stalls.");
    if(!p||!/twilight/i.test(p.label))return "plain twilight assertion lost (precision fix overreached)";
    var q=clockPhaseAssertion("The dusk of the second day settled over the camp.");
    return q&&/dusk/i.test(q.label)?true:"'dusk of the second day' (lowercase of-phrase) must keep its assertion";
  });
  t("prose forms are \\b-anchored derivations of TIME_PHASES — embedded words never match, specificity survives",function(){
    makeClockWorld(310);
    if(clockPhaseAssertion("You reach the Morningstar Inn and stable the horses."))return "'Morningstar' matched morning — the label regexes leaked unanchored into prose";
    if(clockPhaseAssertion("The knight watches from the wall."))return "'knight' matched night";
    var a=clockPhaseAssertion("By mid-morning the frost has burned off.");
    if(!a||!/mid-?morning/i.test(a.label))return "'By mid-morning <state>' is a completed transition (current-phase assertion) and must resolve to the SPECIFIC phase, got: "+JSON.stringify(a);
    var b=clockPhaseAssertion("Late night finds the watch unchanged.");
    if(!b||!/late\s*night/i.test(b.label))return "'late night' must resolve to the SPECIFIC phase, not bare night: "+JSON.stringify(b);
    return true;
  });
  t("recognition positives: current-phase narration parses; the LAST qualifying cue wins across multiple phases",function(){
    makeClockWorld(310);
    var a=clockPhaseAssertion("Dusk catches you on the descent, the fortress crouched below.");
    if(!a||!/dusk/i.test(a.label))return "the reported t1605 sentence did not parse: "+JSON.stringify(a);
    var b=clockPhaseAssertion("Morning comes, grey and cold over the harbor.");
    if(!b||!/morning/i.test(b.label))return "'Morning comes' (the true corpus class) did not parse";
    var c=clockPhaseAssertion("The afternoon march grinds on across the scree. Dusk catches you at the ridge line.");
    if(!c||!/dusk/i.test(c.label))return "multiple phases must resolve to the LAST qualifying cue (narrative recency), got: "+JSON.stringify(c);
    var d=clockPhaseAssertion("Dawn breaks before you, grey and slow over the water.");
    if(!d||!/dawn/i.test(d.label))return "#158b: 'Dawn breaks before you' must still ASSERT — 'before' after the cue is not government (the widened window must not leak backward)";
    return true;
  });
  t("rejections: quoted dialogue, plans, history, figurative, negation, visions, counterfactuals all stay silent",function(){
    makeClockWorld(310);
    var cases=[
      ["“We move at dusk,” she says, checking the straps.","quoted plan"],
      ["\"We move at dusk,\" she says.","straight-quoted plan"],
      ["You'll be back by first light if the pass holds.","future plan"],
      ["The mist has thickened since morning.","historical reference"],
      ["A bruise the color of a bad sunset spreads along his jaw.","figurative"],
      ["It is not dusk yet, whatever the shadows claim.","negation"],
      ["In the dream it was always evening, always this street.","vision"],
      ["She mourns the evening that never got to happen.","counterfactual"],
      ["Will you wait until nightfall?","interrogative plan"],
      ["The plan lands hard. \"Dawn, then,\" you say, checking the crossbow.","spoken plan (speech verb — the t1412 corpus alarm)"],
      ["She nods once. \"Dawn, then. We move quiet and we move first.","spoken plan behind an UNBALANCED quote (the stripper's pairing fails — the sentence must reject, not leak)"],
      ["\"An unclosed opener poisons the pairing. \"Dawn, then,\" you say. \"We hit the warehouse.","the t1412 corpus shape: ODD quote count mispairs the stripper, the spoken plan lands outside quotes with its speech verb eaten — broken parity must distrust the WHOLE entry"],
      ["Gone to finish it, back by first light, and slip out past the sleeping desk.","return-plan idiom (the t1413 corpus alarm)"],
      ["Whatever this afternoon was, it's over now.","retrospective this-<phase> reference (the t1586 corpus alarm)"],
      ["\"Rest. She said nothing more. Dawn comes cold over the pass.","ODD parity with a clean-looking phase sentence — one stray quote makes every outside-quotes judgment a guess, so the WHOLE entry is distrusted (parity guard's own case)"],
      ["\"Dusk. Move.\" The word hangs there.","quoted phase with NO speech verb — only the any-quote-in-sentence rule catches it (that guard's own case)"],
      ["The two of you melt downhill into Magnimar's mist before the first grey hint of dawn touches the rooftops.","STRETCHED before-governed boundary (the t1806 field alarm, #158b) — a modifier run between 'before' and the cue must not defeat the government"]
    ],i;
    for(i=0;i<cases.length;i++){
      var r=clockPhaseAssertion(cases[i][0]);
      if(r)return cases[i][1]+" false-positive: "+JSON.stringify(r)+" on: "+cases[i][0];
    }
    return true;
  });
  t("band distance: in-band = 0, the t1605 case alerts, adjacent-phase slop stays quiet",function(){
    makeClockWorld(310);/* 11:10 am display — clock zero is DAWN(6:00), so 310 = 11:10 */
    var dusk=-1,evening=-1,i;
    for(i=0;i<TIME_PHASES.length;i++){if(/dusk/.test(TIME_PHASES[i].re.source))dusk=i;if(/evening/.test(TIME_PHASES[i].re.source)&&evening<0&&!/dusk/.test(TIME_PHASES[i].re.source))evening=i;}
    var d=clockPhaseBandDist(dusk);
    if(!(d>=PHASE_MISMATCH_MIN))return "11:10 am vs dusk must clear the threshold (got "+d+"m, need >= "+PHASE_MISMATCH_MIN+")";
    worldState.clock.min=760;/* 18:40 — inside the dusk band */
    if(clockPhaseBandDist(dusk)!==0)return "in-band must be 0";
    worldState.clock.min=700;/* 17:40 — inside evening band [690,840) */
    if(clockPhaseBandDist(evening)!==0)return "evening at 17:40 is in-band";
    if(clockPhaseBandDist(dusk)>=PHASE_MISMATCH_MIN)return "17:40 vs dusk is 50m of slop — must stay under the 4h threshold";
    return true;
  });
  t("clockPhaseDetect arms the queue on a real mismatch and self-silences when the same response's [TIME:] healed the clock",function(){
    makeClockWorld(310);
    clockPhaseDetect("Dusk catches you on the descent toward the silent fortress.");
    if(!worldState.phaseMismatch)return "the t1605 shape did not arm";
    if(!/dusk/i.test(worldState.phaseMismatch.label))return "queue carries the wrong label: "+JSON.stringify(worldState.phaseMismatch);
    makeClockWorld(310);
    applyMuts("[TIME:dusk] Dusk catches you on the descent.");/* reconcile lands INSIDE applyMuts */
    clockPhaseDetect(cleanTxt("[TIME:dusk] Dusk catches you on the descent."));
    if(worldState.phaseMismatch)return "a healed clock must self-silence (band agreement) — no covering-tag logic, just math";
    makeClockWorld(310);
    applyMuts("[TIME:morning] Dusk catches you on the descent.");/* the CONTRADICTION class */
    clockPhaseDetect(cleanTxt("[TIME:morning] Dusk catches you on the descent."));
    return worldState.phaseMismatch?true:"a [TIME:morning] tag under dusk narration must STILL alert — tag presence is not agreement (the review's sharpest amendment)";
  });
  t("buildPhaseMismatchNudge: one-shot with the amended phrasing, combat-silent without consuming, stale-agreement discards silently",function(){
    makeClockWorld(310);
    worldState.phaseMismatch={idx:6,label:"dusk",turn:worldState.turn,stamp:"Day 1, 11:10 am"};
    worldState.combat={round:1,engaged:null,foes:[{name:"X",hp:1,maxHp:1,ac:10,atk:0,dmg:"1",morale:"low"}]};
    if(buildPhaseMismatchNudge()!=="")return "fired mid-combat";
    if(!worldState.phaseMismatch)return "combat consumed the queue";
    worldState.combat=null;
    var note=buildPhaseMismatchNudge();
    if(note.indexOf("[TIME:dusk]")<0)return "the exact reconcile tag is missing from: "+note;
    if(!/only a reference|do nothing/i.test(note))return "the do-nothing branch (a reference, not the current phase) is missing — 'correct the prose' is not actionable";
    if(/correct the prose/i.test(note))return "'correct the prose' phrasing survived — the player already read it";
    if(worldState.phaseMismatch)return "note did not consume the queue";
    if(buildPhaseMismatchNudge()!=="")return "re-fired with an empty queue";
    makeClockWorld(760);/* clock now IN the dusk band — a stale armed entry must discard silently */
    worldState.phaseMismatch={idx:6,label:"dusk",turn:worldState.turn,stamp:"stale"};
    if(buildPhaseMismatchNudge()!=="")return "stale agreement must discard, not nag";
    if(worldState.phaseMismatch)return "stale entry not cleared";
    if(NOTE_LATCH_FIELDS.indexOf("phaseMismatch")<0)return "phaseMismatch missing from NOTE_LATCH_FIELDS — the suggestion call would eat the one-shot";
    return true;
  });

