  t("healthIndicators: opt-in growth telemetry reports UTF-8 bytes and counts per logical store without writing or burdening the dot path",function(){
    makeWorld();
    worldState.transcript=[{r:"gm",x:"café 🙂"},{r:"u",x:"go"}];
    worldState.questLog=[{title:"Live",status:"active",objectives:[]}];
    worldState.npcs=[{name:"A"},{name:"B"}];
    memory=blankMemory();
    memory.npcs={A:{knowledge:["one"]},B:{knowledge:[]}};
    memory.quests={Done:{title:"Done",status:"completed"}};
    memory.map={nodes:{Town:{description:"Here"},Road:{}},edges:[{a:"Town",b:"Road"}]};
    memory.archive={lore:["old"],decisions:[{turn:1,desc:"choice"}],chapters:["c1","c2"]};
    var beforeWs=JSON.stringify(worldState),beforeMem=JSON.stringify(memory);
    var h=healthIndicators(worldState,memory,true),g=h.growth||[],by={},i;
    for(i=0;i<g.length;i++)by[g[i].id]=g[i];
    var ids=["transcript","quest-log","roster","npc-memory","quest-history","map","archive"];
    for(i=0;i<ids.length;i++)if(!by[ids[i]])return "missing growth store "+ids[i]+": "+JSON.stringify(g);
    if(by.transcript.count!==2||by["quest-log"].count!==1||by.roster.count!==2)return "world counts wrong: "+JSON.stringify(g);
    if(by["npc-memory"].count!==2||by["quest-history"].count!==1||by.map.count!==2||by.archive.count!==4)return "memory counts wrong: "+JSON.stringify(g);
    var enc=encodeURIComponent(JSON.stringify(worldState.transcript)),expected=enc.replace(/%[0-9A-F]{2}/gi,"x").length;
    if(by.transcript.bytes!==expected)return "transcript byte count is not UTF-8: "+by.transcript.bytes+" vs "+expected;
    if(healthIndicators(worldState,memory).growth!==undefined)return "hot dot path computed opt-in growth telemetry";
    if(JSON.stringify(worldState)!==beforeWs||JSON.stringify(memory)!==beforeMem)return "telemetry mutated its inputs";
    return true;
  });
  // ═══ #189 hardening: split/rejoin transitions are LOUD (owner ruling 2026-08-14) ═══
  // The #133c away-marker already shows standing state; the TRANSITIONS were muts-line-only,
  // which is why an untagged presence fix was invisible at the moment it mattered.
  section("#189: split/rejoin toasts");
  t("[PARTY_SPLIT:] set, explicit |rejoin, and the #133b auto-rejoin fold each fire a toast",function(){
    makeWorld();
    showToast=function(m){__toasts.push(String(m));};/* re-arm the capture — earlier sections reassign the global (the line-8656 precedent) */
    worldState.npcs.push({name:"Daeris",partyMember:true,status:"",statusTurn:0,met:1,charSheet:{name:"Daeris",cls:"Cleric",hp:10,maxHp:10,inventory:[],abilities:[],spells:[],conditions:[],relationships:[]}});
    memory.npcs["Daeris"]={attitude:"",knowledge:[],events:[]};
    __toasts.length=0;
    var R0=applyMuts("[PARTY_SPLIT:Daeris|Shore District]");
    if(!__toasts.some(function(s){return /Daeris/.test(s)&&/splits/.test(s)&&/Shore District/.test(s);}))return "no split toast: "+JSON.stringify(__toasts)+" muts="+JSON.stringify(R0.muts)+" splitLoc="+JSON.stringify((worldState.npcs.filter(function(n){return n.name==="Daeris";})[0]||{charSheet:{}}).charSheet.splitLoc||null);
    __toasts.length=0;
    applyMuts("[PARTY_SPLIT:Daeris|rejoin]");
    if(!__toasts.some(function(s){return /Daeris/.test(s)&&/rejoins/.test(s);}))return "no explicit-rejoin toast: "+JSON.stringify(__toasts);
    /* re-affirmation is SILENT (t1835-1837 field: the GM legally re-emits the split every turn
       to refresh the audit clock — a toast per re-affirm is noise, the transition is the news) */
    applyMuts("[PARTY_SPLIT:Daeris|Shore District]");
    __toasts.length=0;
    applyMuts("[PARTY_SPLIT:Daeris|Shore District]");
    if(__toasts.length)return "re-affirming an unchanged split must NOT toast: "+JSON.stringify(__toasts);
    applyMuts("[PARTY_SPLIT:Daeris|Shore District|The docks]");
    if(!__toasts.some(function(s){return /Daeris/.test(s)&&/The docks/.test(s);}))return "a CHANGED split location must toast: "+JSON.stringify(__toasts);
    applyMuts("[PARTY_SPLIT:Daeris|rejoin]");
    /* auto-rejoin: split to the party's CURRENT node; the #135 grace spares it this response,
       the NEXT response's #133b sweep folds it (Ashfen has no known interiors in this fixture,
       so the #164 granularity gate does not divert it to the audit) */
    applyMuts("[PARTY_SPLIT:Daeris|"+worldState.world.location+"]");
    __toasts.length=0;
    applyMuts("just prose, no tags");
    if(!__toasts.some(function(s){return /Daeris/.test(s)&&/rejoins/.test(s);}))return "no auto-rejoin toast: "+JSON.stringify(__toasts);
    return true;
  });

